--- from: Assets/BundleResources/Prefabs/Chapter/ChapterReviewPopup.prefab
---@class NewChapterReview
---@field Env                           	NewChapterReview                        
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field BtnClose                      	UnityEngine.UI.Button                   
---@field BtnBottomSetting              	UnityEngine.UI.Button                   
---@field BtnTopping                    	UnityEngine.UI.Button                   
---@field ContentLooplist               	SuperScrollView.LoopListView2           
---@field ChapterReviewPopup            	UGUI.Effects.UIEffectCapturedImage      
local NewChapterReview = Class('NewChapterReview')

local CellName = "Cell"

local OptionCnt = 4

local OptionStr = "option%d"

local OptionOrigin = "option"

function NewChapterReview:__init()
    --
    self.cloneData = nil
end

function NewChapterReview:__delete()
    --
    self.cloneData = nil
end

function NewChapterReview:Awake()
end

function NewChapterReview:Start()
    SetButtonAction(self.BtnClose, Bind(self,self.OnBtnCloseClick))
    
    SetButtonAction(self.BtnTopping,function()
        if self.cloneData == nil then
            return
        end

        self.ContentLooplist:MovePanelToItemIndex(#self.cloneData)
    end)
    
    SetButtonAction(self.BtnBottomSetting, function()
        if self.cloneData == nil then
            return
        end

        self.ContentLooplist:MovePanelToItemIndex(0)
    end)
end

function NewChapterReview:OnBtnCloseClick()
    if self.beforeClose ~= nil then
        self.beforeClose(self.controller.gameObject)
        self.beforeClose = nil
    end
    if not isNull(self.afterCo) then
        cs_coroutine.stop(self.afterCo)
        self.afterCo = nil
    end

    CfUtils.SetActive(self.controller.gameObject, false)

    if not isNull(self.backEventHandler) then
        Events.RemoveListener("ANDROID_NATIVE_BACK_ACTION", self.backEventHandler)
    end
    self.ChapterReviewPopup:Release()
    self:Delete()
end

function NewChapterReview:Show(recordData, afterStart, beforeClose)
    self.backEventHandler = Events.AddListener("ANDROID_NATIVE_BACK_ACTION", Bind(self,self.OnBtnCloseClick))
    self.cloneData = clone(checkTable(recordData))
    self.ChapterReviewPopup:Capture()
    self:ReverseData()
    self:Refresh()

    if afterStart ~= nil then
        self.afterCo = cs_coroutine.start(function()
            coroutine.yield(Yielders.EndOfFrame)
            afterStart()
            self.afterCo = nil
        end)
    end
    self.beforeClose = beforeClose
end


function NewChapterReview:Refresh()

    cs_coroutine.start(function()
        local cnt = #self.cloneData
        cs_coroutine.yield_return(Yielders.EndOfFrame)
        if not KTool.IsActiveInHierarchy(self.controller.gameObject) then
            KTool.SetActive(self.controller.gameObject, true)
        end
        if not self.ContentLooplist.IsListViewInit then
            self.ContentLooplist:InitListView(cnt, Bind(self, self.OnRefreshIndex))
        else
            GameUtils.ReloadData(self.ContentLooplist, cnt)
        end
    end)
    
end

function NewChapterReview:OnRefreshIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem(CellName)
    local data = self.cloneData[index + 1]
    --local isCurrent = index == 0
    self:RefreshCell(cell.transform, data, index)
    return cell
end

---{owner, content, option, selectIndex }
function NewChapterReview:RefreshCell(cellTrans, data, index)
    local isCurrent = index == 0
    local bg = cellTrans:Find("ImgBgCurrent").gameObject:GetComponent(typeof(ImageComp))
    bg.enabled = isCurrent
    KTool.SetActive(bg.transform:Find("ImgLine").gameObject, isCurrent)
    local textComp = bg.transform:Find("TextContent").gameObject
    local realTextComp = textComp.gameObject:GetComponent(typeof(TextComp))

    if GameUtils.IsTh() then 
        realTextComp.textAutoAdjustable = false
    end 

    realTextComp.text = data.content
    
    if GameUtils.IsTh() then
        realTextComp.textAutoAdjustable = true
    end
    local roleComp = cellTrans:Find("TextRoleName")
    roleComp.gameObject:GetComponent(typeof(TextComp)).text = data.owner
    KTool.SetActive(roleComp:GetChild(0).gameObject, isCurrent)
    for i = 1, OptionCnt do
        local name = string.format(OptionStr, i)
        local cell = NewChapterReview.GetOrInsTrans(bg.transform, name, OptionOrigin)
        KTool.SetActive(cell.gameObject, false)
    end
    if data.option ~= nil then
        for i = 1, #data.option do
            local name = string.format(OptionStr, i)
            local cell = NewChapterReview.GetOrInsTrans(bg.transform, name, OptionOrigin)
            cell.transform:Find("Text").gameObject:GetComponent(typeof(TextComp)).text = string.format("【%s】", data.option[i])
            KTool.SetActive(cell.gameObject, true)
            local choose = i == data.selectIndex
            local state = choose and 2 or 1
            cell.transform:Find("Text").gameObject:GetComponent(typeof(UISwitchText)).Status = state
            KTool.SetActive(cell.transform:Find("Area/ImgArrowContent"), choose)
        end
    end
    --local optionCnt = data.option == nil and 0 or #data.option
    LayoutRebuilder.ForceRebuildLayoutImmediate(bg.transform)
    --printInfo("%d, %s", index, tostring(LayoutUtility.GetPreferredHeight(bg.transform)))
    cellTrans:SetSizeWithCurrentAnchors(1 , LayoutUtility.GetPreferredHeight(bg.transform) ) 
    --cellTrans.sizeDelta = sizeDelta
    
end

function NewChapterReview.GetOrInsTrans(parent, name, origin)
    local g = parent.transform:Find(name)
    if isNull(g) then
        g = parent.transform:Find(origin)
        g = GameObject.Instantiate(g)
        g.transform:SetParent(parent)
        g.name = name
        g.transform.localPosition = Vector3.New(0, 0, 0)
        g.transform.localScale = Vector3.New(1, 1, 1)
    end
    return g
end

function NewChapterReview:ReverseData()

    local full = #self.cloneData
    local length = math.floor(full / 2)
    for i = 1, length do
        local tmp = self.cloneData[i]
        self.cloneData[i] = self.cloneData[full - i + 1]
        self.cloneData[full - i + 1] = tmp
    end
end

function NewChapterReview:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return NewChapterReview